## Why This Is Asked
This question tests mastery of three key concepts: Trie mutations (insert/delete), weighted dynamic programming for word break problems, and the ability to implement both iterative and recursive approaches. It also evaluates understanding of handling dynamic dictionary updates and edge cases such as when no valid decomposition exists.

## Key Concepts
- Trie with terminal weights for efficient prefix matching
- Dynamic insert/delete operations on Trie structure
- Weighted word-break DP with O(n × L) complexity where L = maxWordLen
- Both iterative bottom-up DP and memoized top-down DFS variants

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.endWeight = 0;
    this.isEnd = false;
  }
}

class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
    this.maxWordLen = 0;
  }

  insert(word, weight) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
    }
    node.isEnd = true;
    node.endWeight = weight;
    this.maxWordLen = Math.max(this.maxWordLen, word.length);
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) return;
      node = node.children.get(char);
    }
    node.isEnd = false;
    node.endWeight = 0;
  }

  maxPartition(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(-1);
    dp[n] = 0;

    for (let i = n - 1; i >= 0; i--) {
      let node = this.root;
      for (let j = i; j < Math.min(n, i + this.maxWordLen); j++) {
        const char = s[j];
        if (!node.children.has(char)) break;
        node = node.children.get(char);
        if (node.isEnd && dp[j + 1] !== -1) {
          dp[i] = Math.max(dp[i], node.endWeight + dp[j + 1]);
        }
      }
    }
    return dp[0];
  }

  maxPartitionDFS(s, memo = {}) {
    if (s.length === 0) return 0;
    if (s in memo) return memo[s];

    let maxWeight = -1;
    let node = this.root;

    for (let i = 0; i < Math.min(s.length, this.maxWordLen); i++) {
      const char = s[i];
      if (!node.children.has(char)) break;
      node = node.children.get(char);

      if (node.isEnd) {
        const remaining = this.maxPartitionDFS(s.slice(i + 1), memo);
        if (remaining !== -1) {
          maxWeight = Math.max(maxWeight, node.endWeight + remaining);
        }
      }
    }
    memo[s] = maxWeight;
    return maxWeight;
  }
}
```

## Why This Is Asked
This question tests the ability to combine shortest-path computation, path counting, and path reconstruction into a cohesive solution. It also evaluates handling of multiple equal-cost routes and lexicographic tie-breaking.

## Key Concepts
- Dijkstra's algorithm for O(m log n) shortest paths
- Shortest-path DAG construction
- Topological ordering by distance values
- DP for counting distinct shortest paths
- Lexicographic path reconstruction

## Code Example
```javascript
function shortestStats(n, edges, s, t) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    adj[u].push([v, w]);
  }

  const dist = new Array(n).fill(Infinity);
  const pq = [[0, s]];
  dist[s] = 0;

  while (pq.length) {
    const [d, u] = pq.pop();
    if (d > dist[u]) continue;
    for (const [v, w] of adj[u]) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        pq.push([dist[v], v]);
      }
    }
  }

  const dag = Array.from({ length: n }, () => []);
  for (let u = 0; u < n; u++) {
    for (const [v, w] of adj[u]) {
      if (dist[u] + w === dist[v]) {
        dag[u].push(v);
      }
    }
  }

  const ways = new Array(n).fill(0);
  ways[s] = 1;
  const order = Array.from({ length: n }, (_, i) => i)
    .sort((a, b) => dist[a] - dist[b]);

  for (const u of order) {
    for (const v of dag[u]) {
      ways[v] = (ways[v] + ways[u]) % 1000000007;
    }
  }

  const path = [];
  let curr = t;
  while (curr !== null) {
    path.unshift(curr);
    const preds = dag
      .map((list, u) => list.includes(curr) ? u : -1)
      .filter(u => u >= 0 && dist[curr] === dist[u] + 
        adj[u].find(([v]) => v === curr)?.[1]);
    preds.sort((a, b) => a - b);
    curr = preds.length > 0 ? preds[0] : null;
    if (curr === s) {
      path.unshift(s);
      break;
    }
  }

  return { distance: dist[t], ways: ways[t], path };
}
```

## Complexity Analysis
- Dijkstra: O(m log n)
- DAG construction: O(m)
- DP counting: O(m)
- Path reconstruction: O(n + m)
- Overall: O(m log n)

## Why This Is Asked
Design a structure to maintain the k-th largest element efficiently in a streaming context, using a heap and a fixed-size container.

## Key Concepts
- Min-heap for thresholding top-k
- Time: O(log k) per insert
- Edge cases: fewer than k elements, duplicates

## Code Example
```javascript
class KthLargest {
  constructor(k, nums = []) {
    this.k = k; this.heap = [];
    for (const n of nums) this.add(n);
  }
  add(val) {
    if (this.heap.length < this.k) { this.heap.push(val); this._bubbleUp(this.heap.length-1); }
    else if (val > this.heap[0]) { this.heap[0] = val; this._siftDown(0); }
    return this.heap.length === this.k ? this.heap[0] : null;
  }
  // ... helpers omitted for brevity
}
```

